320	func versionCacheKey(version string) string {
321		if version == "" || strings.HasPrefix(version, "v") {
322			return version
323		}
324		return "v" + version
325	}
326	
327	func displayVersion(version string) string {
328		return strings.TrimPrefix(version, "v")
329	}
330	
331	func releaseNotesURL(version string) string {
332		return downloadsURL + "/tag/" + versionCacheKey(version)
333	}
